func (v ManifestValue) ToTerraformValue(ctx context.Context) (tftypes.Value, error) {
	attrTypes := make(map[string]tftypes.Type, 13)

	var val tftypes.Value
	var err error

	attrTypes["changelog"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["contract_version"] = basetypes.Int64Type{}.TerraformType(ctx)
	attrTypes["cosign_signature_ref"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["lifecycle_state"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["manifest_capabilities"] = basetypes.ListType{
		ElemType: ManifestCapabilitiesValue{}.Type(ctx),
	}.TerraformType(ctx)
	attrTypes["manifest_digest"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["provider_id"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["published_at"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["published_by"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["signed"] = basetypes.BoolType{}.TerraformType(ctx)
	attrTypes["sunset_at"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["sunset_enforced_at"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["version"] = basetypes.StringType{}.TerraformType(ctx)

	objectType := tftypes.Object{AttributeTypes: attrTypes}

	switch v.state {
	case attr.ValueStateKnown:
		vals := make(map[string]tftypes.Value, 13)

		val, err = v.Changelog.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["changelog"] = val

		val, err = v.ContractVersion.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["contract_version"] = val

		val, err = v.CosignSignatureRef.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["cosign_signature_ref"] = val

		val, err = v.LifecycleState.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["lifecycle_state"] = val

		val, err = v.ManifestCapabilities.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["manifest_capabilities"] = val

		val, err = v.ManifestDigest.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["manifest_digest"] = val

		val, err = v.ProviderId.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["provider_id"] = val

		val, err = v.PublishedAt.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["published_at"] = val

		val, err = v.PublishedBy.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["published_by"] = val

		val, err = v.Signed.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["signed"] = val

		val, err = v.SunsetAt.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["sunset_at"] = val

		val, err = v.SunsetEnforcedAt.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["sunset_enforced_at"] = val

		val, err = v.Version.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["version"] = val

		if err := tftypes.ValidateValue(objectType, vals); err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		return tftypes.NewValue(objectType, vals), nil
	case attr.ValueStateNull:
		return tftypes.NewValue(objectType, nil), nil
	case attr.ValueStateUnknown:
		return tftypes.NewValue(objectType, tftypes.UnknownValue), nil
	default:
		panic(fmt.Sprintf("unhandled Object state in ToTerraformValue: %s", v.state))
	}
}

func (v ManifestValue) IsNull() bool {
	return v.state == attr.ValueStateNull
}

func (v ManifestValue) IsUnknown() bool {
	return v.state == attr.ValueStateUnknown
}

