func (v ManifestValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	manifestCapabilities := types.ListValueMust(
		ManifestCapabilitiesType{
			basetypes.ObjectType{
				AttrTypes: ManifestCapabilitiesValue{}.AttributeTypes(ctx),
			},
		},
		v.ManifestCapabilities.Elements(),
	)

	if v.ManifestCapabilities.IsNull() {
		manifestCapabilities = types.ListNull(
			ManifestCapabilitiesType{
				basetypes.ObjectType{
					AttrTypes: ManifestCapabilitiesValue{}.AttributeTypes(ctx),
				},
			},
		)
	}

	if v.ManifestCapabilities.IsUnknown() {
		manifestCapabilities = types.ListUnknown(
			ManifestCapabilitiesType{
				basetypes.ObjectType{
					AttrTypes: ManifestCapabilitiesValue{}.AttributeTypes(ctx),
				},
			},
		)
	}

	attributeTypes := map[string]attr.Type{
		"changelog":            basetypes.StringType{},
		"contract_version":     basetypes.Int64Type{},
		"cosign_signature_ref": basetypes.StringType{},
		"lifecycle_state":      basetypes.StringType{},
		"manifest_capabilities": basetypes.ListType{
			ElemType: ManifestCapabilitiesValue{}.Type(ctx),
		},
		"manifest_digest":    basetypes.StringType{},
		"provider_id":        basetypes.StringType{},
		"published_at":       basetypes.StringType{},
		"published_by":       basetypes.StringType{},
		"signed":             basetypes.BoolType{},
		"sunset_at":          basetypes.StringType{},
		"sunset_enforced_at": basetypes.StringType{},
		"version":            basetypes.StringType{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"changelog":             v.Changelog,
			"contract_version":      v.ContractVersion,
			"cosign_signature_ref":  v.CosignSignatureRef,
			"lifecycle_state":       v.LifecycleState,
			"manifest_capabilities": manifestCapabilities,
			"manifest_digest":       v.ManifestDigest,
			"provider_id":           v.ProviderId,
			"published_at":          v.PublishedAt,
			"published_by":          v.PublishedBy,
			"signed":                v.Signed,
			"sunset_at":             v.SunsetAt,
			"sunset_enforced_at":    v.SunsetEnforcedAt,
			"version":               v.Version,
		})

	return objVal, diags
}

func (v ManifestValue) Equal(o attr.Value) bool {
	other, ok := o.(ManifestValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Changelog.Equal(other.Changelog) {
		return false
	}

	if !v.ContractVersion.Equal(other.ContractVersion) {
		return false
	}

	if !v.CosignSignatureRef.Equal(other.CosignSignatureRef) {
		return false
	}

	if !v.LifecycleState.Equal(other.LifecycleState) {
		return false
	}

	if !v.ManifestCapabilities.Equal(other.ManifestCapabilities) {
		return false
	}

	if !v.ManifestDigest.Equal(other.ManifestDigest) {
		return false
	}

	if !v.ProviderId.Equal(other.ProviderId) {
		return false
	}

	if !v.PublishedAt.Equal(other.PublishedAt) {
		return false
	}

	if !v.PublishedBy.Equal(other.PublishedBy) {
		return false
	}

	if !v.Signed.Equal(other.Signed) {
		return false
	}

	if !v.SunsetAt.Equal(other.SunsetAt) {
		return false
	}

	if !v.SunsetEnforcedAt.Equal(other.SunsetEnforcedAt) {
		return false
	}

	if !v.Version.Equal(other.Version) {
		return false
	}

	return true
}

